const all=Object.values(groups).flat(),byId=new Map(all.map(f=>[f.id,f]));
const blank=()=>Object.fromEntries([...all.map(f=>[f.id,f.type==='checkbox'?false:f.type==='number'||f.type==='bool'?null:'']),['conditions',[]],['invalidFields',[]]]);
const numericSelections=new Set(['nrsNutrition','nrsDisease','fois']);
const wholeNumbers=new Set(['eat10Total','sppb','saps2Total','iddsiFood','iddsiFluid','sofaGcs']);
export function restoreClinicalMeasures(record){
 const clean=blank(),source=record?.measures;
 if(source&&typeof source==='object'&&!Array.isArray(source)){
  for(const f of all){const v=source[f.id];if(v==null||v==='')continue;let valid=false;
   if(f.type==='number')valid=typeof v==='number'&&Number.isFinite(v)&&v>=f.min&&v<=f.max&&(!wholeNumbers.has(f.id)||Number.isInteger(v));
   else if(f.type==='checkbox'||f.type==='bool')valid=typeof v==='boolean';
   else if(f.type==='select')valid=f.options.some(([key])=>String(v)===key);
   else if(f.type==='date')valid=typeof v==='string'&&dateValid(v);
   else if(f.type==='text')valid=typeof v==='string'&&v.length<=160;
   if(valid)clean[f.id]=numericSelections.has(f.id)?Number(v):v;else clean.invalidFields.push(f.id);
  }
  if(Array.isArray(source.conditions))clean.conditions=source.conditions.filter(id=>conditionOptions.some(([key])=>key===id));
 }
 for(const k of ['functionConfirmed','dysphagiaConfirmed','markerConfirmed','sofaConfirmed','sapsConfirmed','contextReviewed'])clean[k]=false;
 return clean;
}
// Local unfinished drafts retain entered out-of-range values and explicit
// errors. Clinical confirmation is still cleared when a draft is reopened.
export function restoreClinicalDraft(record){
 const clean=restoreClinicalMeasures(record),source=record?.measures;
 if(source&&typeof source==='object'&&!Array.isArray(source)){
  for(const f of all){const value=source[f.id];if(f.type==='number'&&typeof value==='number'&&Number.isFinite(value))clean[f.id]=value;
   else if(['text','date','select'].includes(f.type)&&typeof value==='string'&&value.length<=160)clean[f.id]=numericSelections.has(f.id)&&f.options.some(([key])=>key===value)?Number(value):value;
  }
  if(Array.isArray(source.invalidFields))clean.invalidFields=[...new Set([...clean.invalidFields,...source.invalidFields.filter(id=>byId.has(id))])];
 }
 return clean;
}
export function initClinicalWorkspace({getInput,getResult,getSource,onChange}){
 const $=id=>document.getElementById(id);let measures=blank(),lastLanguage='';
 const metadata=B('Sources, assessment date and explicit clinician verification are required. Missing is not normal.','Kaynak, değerlendirme tarihi ve açık klinisyen doğrulaması gerekir. Eksik, normal demek değildir.');
 function field(f){const id='cx-'+f.id,label=esc(L(f.label));if(f.type==='checkbox')return `<label class="check-field"><input id="${id}" data-clinical-field="${f.id}" type="checkbox" ${measures[f.id]?'checked':''}><span>${label}</span></label>`;
 const value=measures[f.id];const control=f.type==='select'||f.type==='bool'?`<select id="${id}" data-clinical-field="${f.id}"><option value="">${L(B('Not assessed','Değerlendirilmedi'))}</option>${f.options.map(([v,t])=>`<option value="${v}" ${String(f.type==='bool'?(value===true?'yes':value===false?'no':''):value)===v?'selected':''}>${esc(L(t))}</option>`).join('')}</select>`:`<input id="${id}" data-clinical-field="${f.id}" type="${f.type}" value="${esc(value??'')}" ${f.type==='number'?`min="${f.min}" max="${f.max}" step="${['eat10Total','sppb','saps2Total','iddsiFood','iddsiFluid','sofaGcs'].includes(f.id)?1:'any'}"`:f.type==='text'?'maxlength="160"':''} autocomplete="off">`;
 return `<div class="field"><label for="${id}">${label}</label><div class="input-wrap">${control}${f.unit?`<span class="unit">${esc(f.unit)}</span>`:''}</div></div>`;}
 function section(title,key,note=''){return `<section class="card"><h2>${esc(L(title))}</h2>${note?`<p class="footnote">${esc(L(note))}</p>`:''}<div class="fields">${groups[key].map(field).join('')}</div></section>`;}
 function forms(){
  $('criteriaForms').innerHTML=section(B('ESPEN · body composition','ESPEN · vücut bileşimi'),'composition')+section(B('AND/ASPEN · clinician-confirmed characteristics','AND/ASPEN · klinisyenin doğruladığı özellikler'),'aspen',B('Use the original etiology/time/severity definitions. The app counts confirmed characteristics; it does not infer them from albumin.','Özgün etiyoloji/süre/şiddet tanımlarını kullanın. Uygulama doğrulanan özellikleri sayar; albüminden çıkarmaz.'))+section(B('NRS 2002 · original component ratings','NRS 2002 · özgün alt puanlar'),'nrs')+section(B('EWGSOP2 · strength, muscle and performance','EWGSOP2 · güç, kas ve performans'),'function',metadata);
  $('dysphagiaForms').innerHTML=section(B('Swallowing assessment record','Yutma değerlendirme kaydı'),'dysphagia',B('Enter totals/levels from original validated forms and clinical examination. No app-led water challenge or automatic thickener choice.','Özgün valide formlardan ve klinik muayeneden toplam/düzeyleri girin. Uygulama yönlendirmeli su denemesi veya otomatik kıvam artırıcı seçimi yoktur.'));
  $('contextForms').innerHTML=`<section class="card"><h2>${L(B('Known chronic diseases','Bilinen kronik hastalıklar'))}</h2><div class="condition-grid">${conditionOptions.map(([id,title])=>`<label class="check-field"><input type="checkbox" data-condition="${id}" ${measures.conditions.includes(id)?'checked':''}><span>${esc(L(title))}</span></label>`).join('')}</div></section>`+section(B('Disease phase & nutrition suitability','Hastalık fazı ve beslenme uygunluğu'),'context')+section(B('UCR & inflammatory-marker context','UCR ve inflamatuar belirteç bağlamı'),'markers',B('Core-panel creatinine/CRP are reused only after same-date verification. No universal catabolic or inflammation-severity threshold is applied.','Ana panel kreatinin/CRP değerleri yalnız aynı tarih doğrulamasından sonra kullanılır. Evrensel katabolizma veya inflamasyon şiddeti eşiği uygulanmaz.'))+`<details class="card"><summary>${L(B('SOFA-2 · six organ systems (adult ICU)','SOFA-2 · altı organ sistemi (erişkin YBÜ)'))}</summary><p class="footnote">${L(B('Use the worst values in one defined 24-hour window. This is organ dysfunction, not an inflammation scale. Open the original table for support/ceiling exceptions.','Tanımlı tek 24 saatlik penceredeki en kötü değerleri kullanın. Bu organ bozukluğudur; inflamasyon ölçeği değildir. Destek/tedavi sınırı istisnaları için özgün tabloyu açın.'))}</p><div class="fields">${groups.sofa.map(field).join('')}</div></details>`+section(B('SAPS II · clinician-entered total','SAPS II · klinisyenin girdiği toplam'),'saps');
  for(const element of document.querySelectorAll('[data-clinical-field]'))element.addEventListener(element.type==='checkbox'||element.tagName==='SELECT'?'change':'input',event=>{const f=byId.get(element.dataset.clinicalField),raw=event.target.value;measures[f.id]=f.type==='checkbox'?event.target.checked:f.type==='number'?raw===''?null:Number(raw):f.type==='bool'?raw===''?null:raw==='yes':numericSelections.has(f.id)?raw===''?null:Number(raw):raw;measures.invalidFields=measures.invalidFields.filter(id=>id!==f.id);if(!event.target.validity.valid)measures.invalidFields.push(f.id);if(!['functionConfirmed','dysphagiaConfirmed','contextReviewed','markerConfirmed','sofaConfirmed','sapsConfirmed'].includes(f.id)){if(groups.function.some(g=>g.id===f.id))measures.functionConfirmed=false;if(groups.dysphagia.some(g=>g.id===f.id))measures.dysphagiaConfirmed=false;if(groups.context.some(g=>g.id===f.id))measures.contextReviewed=false;if(groups.markers.some(g=>g.id===f.id))measures.markerConfirmed=false;if(groups.sofa.some(g=>g.id===f.id))measures.sofaConfirmed=false;if(groups.saps.some(g=>g.id===f.id))measures.sapsConfirmed=false;for(const id of ['functionConfirmed','dysphagiaConfirmed','contextReviewed','markerConfirmed','sofaConfirmed','sapsConfirmed']){const el=$('cx-'+id);if(el)el.checked=measures[id];}}onChange();});
  for(const el of document.querySelectorAll('[data-condition]'))el.addEventListener('change',()=>{const id=el.dataset.condition;measures.conditions=id==='none'?(el.checked?['none']:[]):[...measures.conditions.filter(c=>c!=='none'&&c!==id),...(el.checked?[id]:[])];measures.contextReviewed=false;forms();onChange();});
  lastLanguage=getLocale();
 }
 function results(){const input=getInput();const fn=evaluateFunction(input,measures);const ctx=evaluateContext(input,measures,fn);if(measures.invalidFields.length)ctx.blockers.push(B('Correct invalid values in the clinical modules.','Klinik modüllerdeki geçersiz değerleri düzeltin.'));return {fn,ctx,malnutrition:evaluateMalnutrition(input,measures),markers:evaluateMarkers(input,measures)};}
 function cards(items){return items.map(r=>`<article class="criteria-card" data-status="${r.status}"><span class="criteria-status">${L({en:{met:'Criterion / candidate pattern',not_met:'Threshold not met',incomplete:'Incomplete assessment',review:'Clinical interpretation'}[r.status],tr:{met:'Ölçüt / aday örüntü',not_met:'Eşik karşılanmadı',incomplete:'Eksik değerlendirme',review:'Klinik yorum'}[r.status]})}</span><h3>${esc(L(r.title))}</h3><p>${esc(L(r.summary))}</p>${r.id==='sofa2'?`<div class="organ-scores">${Object.entries(r.values.components).map(([key,value])=>`<span>${L({brain:B('Brain','Beyin'),respiratory:B('Respiratory','Solunum'),cardiovascular:B('Cardiovascular','Kardiyovasküler'),liver:B('Liver','Karaciğer'),kidney:B('Kidney','Böbrek'),hemostasis:B('Hemostasis','Hemostaz')}[key])}<strong>${value??'—'}</strong></span>`).join('')}</div>`:''}${['bmi','weightLoss','ffmi'].filter(key=>typeof r.values?.[key]==='number').map(key=>`<small class="criterion-value">${L({bmi:B('BMI','BKİ'),weightLoss:B('Weight loss (%)','Ağırlık kaybı (%)'),ffmi:B('FFMI (kg/m²)','FFMI (kg/m²)')}[key])}: ${Number(r.values[key].toFixed(2))}</small>`).join('')}<details class="evidence-details"><summary>${L(B('Interpretation & original sources','Yorum ve özgün kaynaklar'))}</summary>${r.details.map(v=>`<p>${esc(L(v))}</p>`).join('')}${links(r.sourceIds)}</details></article>`).join('');}
 function links(ids){return `<ul>${(ids||[]).map(id=>{const s=getSource?.(id)||additionalSources.find(s=>s.id===id);return s?`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(translate(s.title))} ↗</a><small> · ${esc(translate(s.access))}</small></li>`:'';}).join('')}</ul>`;}
 function refresh(){if(lastLanguage!==getLocale())forms();const r=results(),core=getResult();$('criteriaResults').innerHTML=`<article class="criteria-card"><span class="criteria-status">GLIM · 2025/2026</span><h3>${esc(translate(core.glim.title))}</h3><p>${esc(translate(core.glim.detail))}</p><p class="footnote">${L(B('Uses the main assessment. Candidate criteria, not automatic diagnosis/staging.','Ana değerlendirmeyi kullanır. Aday ölçütlerdir; otomatik tanı/evre değildir.'))}</p>${links(['glim-2025','glim-intake-2026'])}</article>`+cards([...r.malnutrition,r.fn[0]]);
  $('dysphagiaResults').innerHTML=cards(r.fn.filter(v=>v.id!=='ewgsop2'));
  $('contextResults').innerHTML=`<article class="criteria-card"><h3>${esc(translate(core.metabolic.title))}</h3><p>${esc(translate(core.metabolic.detail))}</p><p>${L(B('Nitrogen balance estimates whole-body nitrogen retention/loss under its assumptions; it does not prove net muscle anabolism. UCR, CRP and organ scores are contextual evidence, not automatic dosing switches.','Azot dengesi, varsayımları altında tüm vücut azot tutulumu/kaybını yaklaşık gösterir; net kas anabolizmasını kanıtlamaz. UCR, CRP ve organ puanları bağlamsal kanıttır; otomatik doz anahtarı değildir.'))}</p></article>${r.ctx.blockers.length?`<article class="criteria-card" data-status="review"><h3>${L(B('Context safety checks','Bağlam güvenlik kontrolleri'))}</h3><ul>${r.ctx.blockers.map(v=>`<li>${esc(L(v))}</li>`).join('')}</ul></article>`:''}${r.ctx.notes.length?`<article class="criteria-card"><h3>${L(B('Disease-specific review prompts','Hastalığa özgü değerlendirme başlıkları'))}</h3>${r.ctx.notes.map(v=>`<p>${esc(L(v))}</p>`).join('')}${links(['espen-ibd-2023'])}</article>`:''}${cards(r.markers)}${r.ctx.conditions.includes('ibd')?`<details class="criteria-card scfa-note"><summary>${L(B('IBD adjunct evidence · short-chain fatty acids','İBH ek tedavi kanıtı · kısa zincirli yağ asitleri'))}</summary><p>${L(B('Human IBD trials of microencapsulated oral butyrate exist, including a 140-person 2026-issue trial. In an appropriately matched IBD patient, discuss adjunctive treatment with gastroenterology; no routine or automatic dose is generated.','Mikroenkapsüle oral bütirat için 2026 sayısındaki 140 kişilik çalışma dahil insan İBH deneyleri vardır. Uygun İBH hastasında ek tedavi gastroenterolojiyle değerlendirilebilir; rutin veya otomatik doz üretilmez.'))}</p><p>${L(B('This cannot be generalized to isolated acetate/propionate or all ICU patients. A 103-person rectal SCFA-mixture trial did not show significant overall benefit (p=.14). Formulation, route, disease activity and background therapy matter.','Bu bulgu izole asetat/propiyonata veya tüm YBÜ hastalarına genellenemez. Rektal SCFA karışımının 103 kişilik deneyinde genel yarar anlamlı değildi (p=0,14). Preparat, yol, hastalık aktivitesi ve temel tedavi önemlidir.'))}</p>${links(['butyrate-ibd-print-2026','scfa-mixture-uc-1997','espen-ibd-2023'])}</details>`:''}`;
  $('clinicalReport').innerHTML=`<h3>${L(B('Clinical assessment modules','Klinik değerlendirme modülleri'))}</h3><p>${L(B('Chronic history','Kronik hastalık öyküsü'))}: ${r.ctx.conditions.map(id=>esc(L(conditionOptions.find(([key])=>key===id)?.[1]||id))).join(', ')||L(B('Not assessed','Değerlendirilmedi'))} · ${r.ctx.reviewed?L(B('Reviewed','Değerlendirildi')):L(B('Review required','Değerlendirme gerekli'))}</p><ul>${[...r.malnutrition,...r.fn,...r.markers].map(v=>`<li><strong>${esc(L(v.title))}</strong>: ${esc(L(v.summary))}</li>`).join('')}</ul>${r.ctx.blockers.length?`<ul>${r.ctx.blockers.map(v=>`<li>${esc(L(v))}</li>`).join('')}</ul>`:''}`;
 }
 function reset(demo=false){measures=blank();if(demo){measures.conditions=['none'];measures.contextReviewed=true;}lastLanguage='';refresh();}
 reset(getInput().demo===true);
 return {refresh,reset,getMeasures:()=>structuredClone(measures),getDraft:()=>({measures:structuredClone(measures)}),restoreDraft(record){measures=restoreClinicalDraft(record);lastLanguage='';refresh();},context:()=>results().ctx,snapshot:()=>({version:'2026-10-24',measures:structuredClone(measures),outputs:structuredClone(results())}),invalidateCore(){for(const k of ['functionConfirmed','dysphagiaConfirmed','markerConfirmed','sofaConfirmed','sapsConfirmed','contextReviewed'])measures[k]=false;lastLanguage='';},restore(record){measures=restoreClinicalMeasures(record);lastLanguage='';refresh();}};
}
